const fs = require('fs');
const ALERTAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md';

const dado = $input.first().json;
const nomeWorkflow = (dado.workflow && dado.workflow.name) || 'desconhecido';
const execId = dado.execution && dado.execution.id;
const erroMsg = (dado.execution && dado.execution.error && dado.execution.error.message) || JSON.stringify(dado).slice(0, 300);

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;

const bloco = `\n## ${dataStr} ${horaStr} — n8n MISSION CONTROL — FALHA REAL\n\nWorkflow "${nomeWorkflow}" falhou (execução ${execId || '?'}). Erro: ${erroMsg}\n\nIsso não é um alerta de rotina — é o próprio mecanismo de monitoramento que quebrou. Precisa de atenção do Diretor antes de confiar nos outros alertas.\n`;

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { nomeWorkflow, erroMsg } }];
